  [new Date(2026,0,31,10,30), 1, '2026-02-28 10:30'],
  [new Date(2024,0,31,10,30), 1, '2024-02-29 10:30'],
  [new Date(2026,2,31), 1, '2026-04-30'],
  [new Date(2026,0,15), 1, '2026-02-15'],
  [new Date(2026,0,31), 12, '2027-01-31'],
  [new Date(2026,2,31), -1, '2026-02-28'],
  [new Date(2024,1,29), 12, '2025-02-28'],
  [new Date(2026,0,31), 0, '2026-01-31'],
];
let ok = true;
for (const [input, n, expected] of cases) {
  const got = fmt(addMonths(input, n));
  const pass = got === expected;
  ok = ok && pass;
  console.log(pass ? 'PASS' : 'FAIL', fmt(input), n, '->', got, pass ? '' : '(expected '+expected+')');
}
const orig = new Date(2026,0,31,10,30).getTime();
const x = new Date(orig); addMonths(x, 1);
console.log(x.getTime() === orig ? 'PASS input not mutated' : 'FAIL input mutated');
console.log(ok ? 'ALL PASS' : 'SOME FAILED');
"

